{
  "$schema": "https://opencode.ai/config.json",
  "agent": {
    "memorize": {
      "mode": "subagent",
      "prompt": "You are a memory consolidation agent. Follow the supplied version-specific consolidation contract and update only its requested artifacts under the supplied memory workspace. Do not read or edit project source files or a different memory workspace. Keep memory_summary.md under 10000 bytes. Prune stale entries. Do not access the network.",
      "permission": {
        "*": "deny",
        "bash": "deny",
        "webfetch": "deny",
        "websearch": "deny",
        "task": "deny",
        "todowrite": "deny",
        "read": "allow",
        "edit": "allow",
        "write": "allow",
        "glob": "allow",
        "grep": "allow"
      }
    },
    "memorize-extract": {
      "mode": "subagent",
      "prompt": "You are a memory extraction agent. The session transcript is provided inline in the prompt. Follow the supplied version-specific JSON schema. Exclude AGENTS.md/instruction content. Redact secrets.",
      "permission": {
        "*": "deny",
        "bash": "deny",
        "webfetch": "deny",
        "websearch": "deny",
        "task": "deny",
        "todowrite": "deny",
        "read": "deny",
        "write": "deny",
        "edit": "deny",
        "glob": "deny",
        "grep": "deny",
        "StructuredOutput": "allow"
      }
    }
  }
}

{
  "name": "opencode-codex-memory",
  "version": "0.10.1",
  "description": "Persistent memory plugin for opencode — ports codex's two-phase memory system (extraction → consolidation → injection → citation feedback)",
  "type": "module",
  "main": "./dist/src/index.js",
  "exports": {
    ".": {
      "import": "./dist/src/index.js",
      "types": "./dist/src/index.d.ts"
    },
    "./server": {
      "import": "./dist/src/index.js",
      "types": "./dist/src/index.d.ts"
    },
    "./v2": {
      "import": "./dist/src/v2/index.js",
      "types": "./dist/src/v2/index.d.ts"
    },
    "./tui": {
      "types": "./dist/src/tui.d.ts",
      "import": "./dist/src/tui.js"
    },
    "./tools/*": {
      "import": "./dist/tools/*.js",
      "types": "./dist/tools/*.d.ts"
    }
  },
  "files": [
    "dist",
    "server.js",
    "tui.js",
    "opencode.json",
    "NOTICE"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/moritzfl/opencode-codex-memory.git"
  },
  "homepage": "https://github.com/moritzfl/opencode-codex-memory#readme",
  "bugs": {
    "url": "https://github.com/moritzfl/opencode-codex-memory/issues"
  },
  "scripts": {
    "dev": "bun --watch src/index.ts",
    "build": "rm -rf dist && tsc && bun scripts/build-tui.ts && cp -R src/templates dist/src/templates && cp opencode.json dist/opencode.json",
    "smoke": "bun scripts/smoke.ts",
    "contract": "bun scripts/check-opencode-contract.ts",
    "contract:v2": "bun scripts/check-opencode2-contract.ts",
    "live:read": "bun scripts/live-readpath.ts",
    "live:e2e": "bun scripts/live-e2e.ts",
    "prepack": "npm run build && npm run smoke",
    "test": "bun test",
    "typecheck": "tsc --noEmit -p tsconfig.typecheck.json"
  },
  "keywords": [
    "opencode",
    "memory",
    "plugin",
    "ai",
    "persistent-context",
    "codex"
  ],
  "license": "Apache-2.0",
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.0",
    "@opencode/client": "2.0.5",
    "diff": "^9.0.0",
    "isomorphic-git": "^1.38.6",
    "xdg-basedir": "^5.1.0",
    "zod": "4.1.8"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.3",
    "@opencode/theme": "2.0.3",
    "@opentui/core": "0.5.10",
    "@opentui/solid": "0.5.10",
    "solid-js": "1.9.15",
    "typescript": "^5.5.0",
    "@types/bun": "^1.1.0"
  },
  "peerDependencies": {
    "@opencode/client": ">=2.0.3",
    "@opencode/plugin": ">=2.0.3",
    "@opentui/core": ">=0.5.10",
    "@opentui/solid": ">=0.5.10",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/client": { "optional": true },
    "@opencode/plugin": { "optional": true },
    "@opentui/core": { "optional": true },
    "@opentui/solid": { "optional": true },
    "solid-js": { "optional": true }
  },
  "engines": {
    "bun": ">=1.1.0"
  }
}

